@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
.ui-root { --ui-primary: #A99BD4; --ui-primary-text: #111111; --ui-bg: #1B1721; --ui-surface: #2A2432; --ui-surface-2: color-mix(in srgb, #E4DDEE 6%, #2A2432); --ui-text: #E4DDEE; --ui-muted: #9B91AD; --ui-border: color-mix(in srgb, #E4DDEE 14%, #1B1721); --ui-success: #8DB59A; --ui-warning: #d97706; --ui-danger: #C96B7E; --ui-info: #2563eb; --ui-radius: 8px; --ui-radius-sm: calc(8px / 2); --ui-space: 4px; --ui-shadow: 0 1px 2px rgb(0 0 0 / 0.4), 0 6px 16px rgb(0 0 0 / 0.35); --ui-font: 'Inter', system-ui, sans-serif; --ui-font-heading: 'Inter', system-ui, sans-serif; font-family: var(--ui-font); font-size: 15px; line-height: 1.5; color: var(--ui-text); background: var(--ui-bg); }
.ui-root h1, .ui-root h2, .ui-root h3 { font-family: var(--ui-font-heading); }

/* Page header */
.ui-root .ui-page { display: flex; flex-direction: column; gap: calc(var(--ui-space) * 12); width: 100%; max-width: 1200px; margin: 0 auto; padding: calc(var(--ui-space) * 12) calc(var(--ui-space) * 6); box-sizing: border-box; color: var(--ui-text); font-family: var(--ui-font); }
.ui-root .ui-page-header { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: calc(var(--ui-space) * 4); padding-bottom: calc(var(--ui-space) * 6); border-bottom: 1px solid var(--ui-border); }
