.ui-root .ui-page-header h1 { margin: 0; font-family: var(--ui-font-heading); font-size: calc(var(--ui-space) * 9); font-weight: 700; line-height: 1.2; letter-spacing: -0.01em; color: var(--ui-text); }
.ui-root .ui-meta { margin: 0; font-size: 14px; line-height: 1.5; color: var(--ui-muted); }
