/* Cards */
.ui-root .ui-card { display: flex; flex-direction: column; background: var(--ui-surface); color: var(--ui-text); border: 1px solid var(--ui-border); border-radius: calc(var(--ui-radius) * 2); box-shadow: var(--ui-shadow); overflow: hidden; font-family: var(--ui-font); font-size: 15px; line-height: 1.5; min-width: 0; }
.ui-root .ui-card-header { display: flex; align-items: center; justify-content: space-between; gap: calc(var(--ui-space) * 3); padding: calc(var(--ui-space) * 4) calc(var(--ui-space) * 6); border-bottom: 1px solid var(--ui-border); background: var(--ui-surface-2); }
.ui-root .ui-card-header h1, .ui-root .ui-card-header h2, .ui-root .ui-card-header h3, .ui-root .ui-card-header h4 { margin: 0; font-family: var(--ui-font-heading); font-size: 18px; font-weight: 600; line-height: 1.3; color: var(--ui-text); }
