.ui-root .ui-card-link { display: flex; text-decoration: none; color: var(--ui-text); cursor: pointer; transition: border-color 0.15s ease, box-shadow 0.15s ease; }
.ui-root .ui-card-link:hover { border-color: var(--ui-primary); box-shadow: var(--ui-shadow), 0 0 0 1px var(--ui-primary); }
.ui-root .ui-card-link:hover .ui-card-header h3, .ui-root .ui-card-link:hover .ui-card-header h2 { color: var(--ui-primary); }
.ui-root .ui-card-link:focus-visible { outline: 2px solid var(--ui-primary); outline-offset: 3px; }
.ui-root .ui-card-link .ui-card-body { width: 100%; }
.ui-root .ui-card-header + .ui-card-footer, .ui-root .ui-card-body + .ui-card-footer { border-top: 1px solid var(--ui-border); }
@media (max-width: 899px) {
  .ui-root .ui-card-header { flex-wrap: wrap; padding: calc(var(--ui-space) * 3) calc(var(--ui-space) * 4); }
  .ui-root .ui-card-body { padding: calc(var(--ui-space) * 4); }
  .ui-root .ui-card-footer { padding: calc(var(--ui-space) * 3) calc(var(--ui-space) * 4); }
}

/* Lists */
.ui-root .ui-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; background: var(--ui-surface); border: 1px solid var(--ui-border); border-radius: calc(var(--ui-radius) * 1.5); box-shadow: var(--ui-shadow); overflow: hidden; font-family: var(--ui-font); font-size: 15px; line-height: 1.5; color: var(--ui-text); }
.ui-root .ui-list-item { display: flex; align-items: center; justify-content: space-between; gap: calc(var(--ui-space) * 4); padding: calc(var(--ui-space) * 4) calc(var(--ui-space) * 6); margin: 0; border-top: 1px solid var(--ui-border); background: transparent; transition: background-color 150ms ease; }
.ui-root .ui-list-item:first-child { border-top: none; }
.ui-root .ui-list-item:hover { background: var(--ui-surface-2); }
