.ui-root .ui-list-main { display: flex; flex-direction: column; gap: var(--ui-space); min-width: 0; flex: 1 1 auto; }
.ui-root .ui-list-main strong { font-family: var(--ui-font-heading); font-weight: 600; font-size: 15px; color: var(--ui-text); overflow-wrap: anywhere; }
.ui-root .ui-list-side { display: flex; align-items: center; justify-content: flex-end; gap: calc(var(--ui-space) * 2); flex-shrink: 0; text-align: right; }
