/* Buttons and links */
.ui-root .ui-btn { display: inline-flex; align-items: center; justify-content: center; gap: calc(var(--ui-space) * 2); min-height: 44px; padding: calc(var(--ui-space) * 2.5) calc(var(--ui-space) * 5); border: 1px solid transparent; border-radius: 999px; font-family: var(--ui-font); font-size: 15px; font-weight: 600; line-height: 1.2; text-decoration: none; white-space: nowrap; cursor: pointer; transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease, box-shadow 150ms ease, transform 150ms ease; }
