.ui-root .ui-btn.is-disabled, .ui-root .ui-btn[disabled] { opacity: 0.5; cursor: not-allowed; box-shadow: none; transform: none; }
.ui-root .ui-link { color: var(--ui-primary); font-family: var(--ui-font); font-size: 15px; font-weight: 500; text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; border-radius: var(--ui-radius-sm); transition: color 150ms ease; }
