/* Badges and people */
.ui-root .ui-badge { display: inline-flex; align-items: center; gap: calc(var(--ui-space) * 1); padding: calc(var(--ui-space) * 1) calc(var(--ui-space) * 3); border: 1px solid var(--ui-border); border-radius: 999px; background: var(--ui-surface-2); color: var(--ui-text); font-family: var(--ui-font); font-size: 14px; font-weight: 600; line-height: 1.2; letter-spacing: 0.01em; white-space: nowrap; transition: background-color 150ms ease, border-color 150ms ease; }
.ui-root .ui-badge::before { content: ""; width: 6px; height: 6px; border-radius: 999px; background: currentColor; flex: none; }
.ui-root .ui-badge-success { background: color-mix(in srgb, var(--ui-success) 22%, var(--ui-surface)); border-color: color-mix(in srgb, var(--ui-success) 50%, var(--ui-surface)); color: var(--ui-text); }
