.ui-root .ui-badge-warning::before { background: var(--ui-warning); }
.ui-root .ui-badge-danger { background: color-mix(in srgb, var(--ui-danger) 22%, var(--ui-surface)); border-color: color-mix(in srgb, var(--ui-danger) 50%, var(--ui-surface)); color: var(--ui-text); }
