.ui-root .ui-avatar { display: inline-flex; align-items: center; justify-content: center; width: 40px; height: 40px; flex: none; border-radius: 999px; background: var(--ui-primary); color: var(--ui-primary-text); border: 1px solid color-mix(in srgb, var(--ui-primary) 60%, var(--ui-surface)); box-shadow: var(--ui-shadow); font-family: var(--ui-font-heading); font-size: 14px; font-weight: 700; letter-spacing: 0.02em; line-height: 1; text-transform: uppercase; user-select: none; transition: box-shadow 150ms ease; }
