/* Stats */
.ui-root .ui-stat { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: var(--ui-space); min-width: 0; padding: calc(var(--ui-space) * 6); padding-top: calc(var(--ui-space) * 8); background: var(--ui-surface); border: 1px solid var(--ui-border); border-radius: calc(var(--ui-radius) * 1.5); box-shadow: var(--ui-shadow); color: var(--ui-text); transition: border-color 0.15s ease, box-shadow 0.15s ease; }
.ui-root .ui-stat::before { content: ""; position: absolute; top: calc(var(--ui-space) * 4); left: calc(var(--ui-space) * 6); width: calc(var(--ui-space) * 8); height: var(--ui-space); border-radius: 999px; background: var(--ui-primary); }
.ui-root .ui-stat:hover { border-color: color-mix(in srgb, var(--ui-primary) 40%, var(--ui-border)); box-shadow: var(--ui-shadow), 0 0 0 1px color-mix(in srgb, var(--ui-primary) 12%, transparent); }
.ui-root .ui-stat-label { display: block; font-family: var(--ui-font); font-size: 14px; font-weight: 500; line-height: 1.4; letter-spacing: 0.01em; color: var(--ui-muted); }
.ui-root .ui-stat-value { display: block; margin-top: calc(var(--ui-space) * 1); font-family: var(--ui-font-heading); font-size: 32px; font-weight: 700; line-height: 1.2; letter-spacing: -0.01em; font-variant-numeric: tabular-nums; color: var(--ui-text); }
.ui-root .ui-stat-note { display: inline-block; margin-top: calc(var(--ui-space) * 1); padding: calc(var(--ui-space) * 1) calc(var(--ui-space) * 3); border: 1px solid var(--ui-border); border-radius: 999px; background: var(--ui-bg); font-family: var(--ui-font); font-size: 14px; font-weight: 500; line-height: 1.4; color: var(--ui-success); }

/* Progress */
.ui-root .ui-progress { position: relative; display: block; width: 100%; height: 12px; margin: calc(var(--ui-space) * 4) 0; padding: 0; overflow: hidden; background: var(--ui-surface-2); border: 1px solid var(--ui-border); border-radius: 999px; box-shadow: inset 0 1px 2px rgb(0 0 0 / 0.3); }
.ui-root .ui-progress > span { display: block; height: 100%; max-width: 100%; min-width: 0; background: var(--ui-primary); border-radius: 999px; box-shadow: 0 1px 2px rgb(0 0 0 / 0.4); }
