/* Details */
.ui-root .ui-kv { display: grid; grid-template-columns: minmax(120px, max-content) minmax(0, 1fr); column-gap: calc(var(--ui-space) * 6); margin: 0; padding: calc(var(--ui-space) * 4) calc(var(--ui-space) * 6); background: var(--ui-surface); color: var(--ui-text); border: 1px solid var(--ui-border); border-radius: calc(var(--ui-radius) * 1.5); box-shadow: var(--ui-shadow); font-family: var(--ui-font); font-size: 15px; line-height: 1.5; }
.ui-root .ui-kv dt, .ui-root .ui-kv dd { margin: 0; padding: calc(var(--ui-space) * 3) 0; border-top: 1px solid var(--ui-border); font-size: 14px; line-height: 1.5; }
.ui-root .ui-kv dt:first-of-type, .ui-root .ui-kv dd:first-of-type { border-top: 0; }
.ui-root .ui-kv dt { color: var(--ui-muted); font-weight: 500; font-family: var(--ui-font-heading); }
.ui-root .ui-kv dd { color: var(--ui-text); font-weight: 500; text-align: left; overflow-wrap: anywhere; }
.ui-root .ui-kv dd.is-active { color: var(--ui-primary); }
.ui-root .ui-kv dd.is-disabled { color: var(--ui-muted); opacity: 0.8; }
@media (max-width: 600px) {
  .ui-root .ui-kv { grid-template-columns: minmax(0, 1fr); column-gap: 0; padding: calc(var(--ui-space) * 3) calc(var(--ui-space) * 4); }
  .ui-root .ui-kv dt { padding-bottom: 0; border-top: 0; }
  .ui-root .ui-kv dt:not(:first-of-type) { margin-top: calc(var(--ui-space) * 2); border-top: 1px solid var(--ui-border); padding-top: calc(var(--ui-space) * 3); }
  .ui-root .ui-kv dd { padding-top: calc(var(--ui-space) * 1); border-top: 0; }
}

/* Timeline */
.ui-root .ui-timeline { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: calc(var(--ui-space) * 5); font-family: var(--ui-font); }
