.ui-root .ui-timeline-item::after { content: ""; position: absolute; left: 0; top: 4px; width: 16px; height: 16px; border-radius: 999px; background: var(--ui-primary); box-shadow: 0 0 0 4px var(--ui-surface), var(--ui-shadow); }
.ui-root .ui-timeline-time { display: inline-block; margin-bottom: var(--ui-space); padding: var(--ui-space) calc(var(--ui-space) * 3); border: 1px solid var(--ui-border); border-radius: 999px; background: var(--ui-surface-2); color: var(--ui-muted); font-family: var(--ui-font); font-size: 14px; font-weight: 500; line-height: 1.4; transition: color 150ms ease, border-color 150ms ease; }
.ui-root .ui-timeline-item:hover .ui-timeline-time { color: var(--ui-text); border-color: var(--ui-primary); }
.ui-root .ui-timeline-item p { margin: 0; color: var(--ui-text); font-family: var(--ui-font); font-size: 15px; line-height: 1.5; }

/* Messages and empty states */
.ui-root .ui-empty { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: calc(var(--ui-space) * 3); padding: calc(var(--ui-space) * 12) calc(var(--ui-space) * 6); text-align: center; background: var(--ui-surface); color: var(--ui-text); border: 1px solid var(--ui-border); border-radius: calc(var(--ui-radius) * 2); box-shadow: var(--ui-shadow); font-family: var(--ui-font); }
.ui-root .ui-empty-title { margin: 0; font-family: var(--ui-font-heading); font-size: 20px; font-weight: 600; line-height: 1.3; color: var(--ui-text); }
